using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CompanionsList", menuName = "Data/Battle/Companions/Companion List")]
public class CompanionsList : ScriptableObject
{
	[Header("Area")]
	[SerializeField]
	private bool enableCharacter = true;

	[SerializeField]
	[ShowIf("enableCharacter")]
	private Character character;

	[Header("Basic Dices")]
	[SerializeField]
	private List<CompanionData> companions = new List<CompanionData>();

	public Character Character => character;

	public List<CompanionData> Companions => companions;

	public CompanionData GetCompanionData(string companionName, bool logError = true)
	{
		string text = companionName.ToLower();
		for (int i = 0; i < companions.Count; i++)
		{
			if (text == companions[i].name.ToLower())
			{
				return companions[i];
			}
		}
		return null;
	}

	public void ClearModdedCompanions()
	{
		companions.RemoveNullObjects();
	}
}
